"""aya-db-agent SFT pilot on Kaggle T4x2. Generated by scripts/kaggle_job.py. Private; publishes nothing.

Stages: setup (Python 3.12 venv, torch 2.11 cu126) -> official model download (HF token from the
Kaggle secret HF_TOKEN) -> kcheck -> mini stage (2 train steps, 2 eval tasks; abort on failure)
-> GPU0: QLoRA train, SFT nf4 eval x2 (A/A) | GPU1: base fp16 eval, base nf4 eval, SFT fp16 eval.
All evaluations: frozen dev set, multistep-close protocol, greedy, 8 tool rounds.
"""

import base64
import io
import json
import os
import subprocess
import sys
import threading
import time
import zipfile
from pathlib import Path

PAYLOAD = "__PAYLOAD__"
JOB = json.loads(r'''__JOB__''')
W, TMP = Path("/kaggle/working"), Path("/kaggle/tmp")
OUT, REPO, VENV = W / "out", TMP / "aya-db-agent", TMP / "venv"
PY = str(VENV / "bin" / "python")
MODEL = "CohereLabs/tiny-aya-global"
STATUS = {"job": JOB["name"], "created": JOB["created"], "git": JOB["git"], "phases": {}, "gpu_mem_max_mib": {}}
EVAL = ["-m", "ayadb.smoke", "--engine", "hf", "--hf-model", MODEL, "--split", "dev",
        "--format", "multistep-close", "--temperature", "0", "--max-steps", "8", "--out", str(OUT / "runs")]


def log(msg):
    line = f"{time.strftime('%H:%M:%S')} {msg}"
    print(line, flush=True)
    with open(OUT / "job_log.txt", "a") as f:
        f.write(line + "\n")


def save_status(**kw):
    STATUS.update(kw)
    (OUT / "job_status.json").write_text(json.dumps(STATUS, indent=2))


def run(name, args, gpu=None, timeout=None, env=None):
    e = dict(os.environ, HF_HOME=str(TMP / "hf"), PYTHONUNBUFFERED="1", PYTHONWARNINGS="ignore", **(env or {}))
    if gpu is not None:
        e["CUDA_VISIBLE_DEVICES"] = str(gpu)
    t0 = time.time()
    log(f"start {name} (gpu {gpu})")
    with open(OUT / f"{name}.log", "w") as f:
        try:
            rc = subprocess.run(args, cwd=REPO, env=e, stdout=f, stderr=subprocess.STDOUT,
                                timeout=timeout).returncode
        except subprocess.TimeoutExpired:
            rc = "timeout"
    STATUS["phases"][name] = {"rc": rc, "seconds": round(time.time() - t0, 1), "gpu": gpu}
    save_status()
    log(f"end {name}: rc={rc} in {STATUS['phases'][name]['seconds']}s")
    return rc


def sample_gpu_memory(stop):
    while not stop.is_set():
        try:
            q = subprocess.run(["nvidia-smi", "--query-gpu=index,memory.used", "--format=csv,noheader,nounits"],
                               capture_output=True, text=True).stdout
            for line in q.strip().splitlines():
                i, used = (int(x) for x in line.split(","))
                STATUS["gpu_mem_max_mib"][str(i)] = max(STATUS["gpu_mem_max_mib"].get(str(i), 0), used)
        except Exception:
            pass
        stop.wait(10)


def lane(steps):
    """Run steps in order on one GPU; steps that need the adapter wait for training to end."""
    def go():
        for name, args, gpu, timeout, needs in steps:
            if needs is not None:
                needs.wait()
                if STATUS["phases"].get("train", {}).get("rc") != 0:
                    log(f"skip {name}: training failed")
                    continue
            run(name, args, gpu, timeout, HF_ENV)
            if name == "train":
                TRAINED.set()
    return threading.Thread(target=go)


def main():
    global HF_ENV, TRAINED
    OUT.mkdir(parents=True, exist_ok=True)
    zipfile.ZipFile(io.BytesIO(base64.b64decode(PAYLOAD))).extractall(REPO)
    save_status(result="RUNNING")
    log("gpus: " + subprocess.run(["nvidia-smi", "--query-gpu=name,memory.total,driver_version",
                                   "--format=csv,noheader"], capture_output=True, text=True).stdout.strip())
    try:
        from kaggle_secrets import UserSecretsClient
        token = UserSecretsClient().get_secret("HF_TOKEN")
    except Exception as e:
        save_status(result="NO_HF_TOKEN", detail=f"{type(e).__name__}")
        log("no HF_TOKEN secret attached to this notebook; stopping")
        return
    HF_ENV = {"HF_TOKEN": token}
    TRAINED = threading.Event()

    if run("setup_uv", [sys.executable, "-m", "pip", "install", "-q", "uv"]) != 0 or \
            run("setup_venv", [sys.executable, "-m", "uv", "venv", "--python", "3.12", str(VENV)]) != 0 or \
            run("setup_torch", [sys.executable, "-m", "uv", "pip", "install", "--python", PY, "-q",
                                "torch==2.11.0", "--index-url", "https://download.pytorch.org/whl/cu126"]) != 0 or \
            run("setup_repo", [sys.executable, "-m", "uv", "pip", "install", "--python", PY, "-q",
                               "-e", str(REPO), "bitsandbytes"]) != 0:
        save_status(result="SETUP_FAILED")
        return
    run("env_info", [PY, "-c", "import torch, transformers, peft, bitsandbytes, agenttune; "
                     "print(torch.__version__, torch.version.cuda, torch.cuda.is_available(), "
                     "torch.cuda.device_count(), transformers.__version__, peft.__version__, "
                     "bitsandbytes.__version__, agenttune.__version__)"])
    if run("download", [PY, "-c", f"from huggingface_hub import snapshot_download; snapshot_download('{MODEL}')"],
           env=HF_ENV) != 0:
        save_status(result="NO_MODEL_ACCESS")
        return
    if run("kcheck", [PY, "-m", "ayadb.kcheck", "--model", MODEL, "--out", str(OUT / "kcheck.json"),
                      "--data", str(TMP / "data-kcheck")], env=HF_ENV) != 0:
        save_status(result="CHECK_FAILED")
        return

    sane = {p: run(f"sanity_{p}", [PY, "-m", "ayadb.sanity", "--out", str(OUT / f"sanity_{p}.json"),
                                   *(["--load-4bit"] if p == "nf4" else [])], 0, 1800, HF_ENV) == 0
            for p in ("fp16", "nf4")}
    if not sane["nf4"]:
        save_status(result="NF4_INFERENCE_BROKEN")  # training and SFT evals all use the nf4 base
        return

    stop = threading.Event()
    threading.Thread(target=sample_gpu_memory, args=(stop,), daemon=True).start()
    sft = [PY, "-m", "ayadb.sft", "--model", MODEL, "--episodes", "data/sft_pilot/episodes.jsonl"]
    if run("mini_train", sft + ["--max-steps", "2", "--out", str(TMP / "mini")], 0, 1800, HF_ENV) != 0 or \
            run("mini_eval", [PY] + EVAL + ["--limit", "2", "--tag", "mini", "--data", str(TMP / "data-mini"),
                                            "--adapter", str(TMP / "mini" / "adapter"), "--load-4bit",
                                            "--out", str(TMP / "mini-runs")], 0, 1800, HF_ENV) != 0:
        save_status(result="MINI_FAILED")
        stop.set()
        return
    adapter = str(OUT / "sft-pilot" / "adapter")

    def ev(tag, *extra):
        return [PY] + EVAL + ["--tag", tag, "--data", str(TMP / f"data-{tag}"), *extra]

    gpu0 = lane([("train", sft + ["--out", str(OUT / "sft-pilot")], 0, 5400, None),
                 ("eval_sft_nf4_r0", ev("sft-nf4-r0", "--adapter", adapter, "--load-4bit"), 0, 7200, TRAINED),
                 ("eval_sft_nf4_r1", ev("sft-nf4-r1", "--adapter", adapter, "--load-4bit"), 0, 7200, TRAINED)])
    fp16 = [("eval_base_fp16", ev("base-fp16"), 1, 7200, None)] if sane["fp16"] else []
    fp16_sft = [("eval_sft_fp16", ev("sft-fp16", "--adapter", adapter), 1, 7200, TRAINED)] if sane["fp16"] else []
    gpu1 = lane(fp16 + [("eval_base_nf4", ev("base-nf4", "--load-4bit"), 1, 7200, None)] + fp16_sft)
    gpu0.start(); gpu1.start(); gpu0.join(); gpu1.join()
    stop.set()
    failed = [k for k, v in STATUS["phases"].items() if v["rc"] != 0]
    save_status(result="DONE" if not failed else "DONE_WITH_FAILURES", failed=failed)
    log(f"finished: {STATUS['result']}")


if __name__ == "__main__":
    main()
